using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Text;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            Action<float, float> click = (x, y) =>
            {
                var p = new Vector2(x * Screen.width / 1200 / 1.25f, y * Screen.height / 800 / 1.25f + 55);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            };
            int i = 0;
            double next = EditorApplication.timeSinceStartup + .5;
            var b = new StringBuilder("Synthetic GameView clip controls; inspect screenshot on failure.\n");
            EditorApplication.CallbackFunction f = null;
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + .8;
                switch (i++)
                {
                    case 0:
                        click(120, 264);
                        break;
                    case 1:
                        b.AppendLine("sidebar=" + s.Page + " play=" + s.ClipPlaying + " t=" + s.ClipTime);
                        click(450, 555);
                        break;
                    case 2:
                        b.AppendLine("pause play=" + s.ClipPlaying + " t=" + s.ClipTime);
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/clip-controls-paused.png");
                        break;
                    case 3:
                        click(950, 639);
                        break;
                    case 4:
                        b.AppendLine("seek play=" + s.ClipPlaying + " t=" + s.ClipTime);
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/clip-controls-seek.png");
                        break;
                    case 5:
                        click(950, 555);
                        break;
                    case 6:
                        b.AppendLine("replay play=" + s.ClipPlaying + " t=" + s.ClipTime);
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/clip-controls-replay.png");
                        EditorApplication.update -= f;
                        File.WriteAllText("Test/KetQua/investigation_r103/clip-controls-ui.txt", b.ToString());
                        break;
                }
            };
            EditorApplication.update += f;
            r.Log("Clip UI control check");
        }
    }
}

